// gh-1832 regression guards: release v1.0.635 published without
// fa-extension.zip because the tag train (ci.yml release-provenance)
// publishes whatever the release happens to carry and the extension's only
// producer (build-macos.yml `Build Chrome extension`) attaches to a tag it
// derives as "latest+1 at its own dispatch moment". Guards:
//   1. one required-assets list (single source of truth) exists and is
//      well-formed;
//   2. the tag train's publish point (`gh release edit --draft=false
//      --latest`) is gated by scripts/assert_release_assets.sh — a missing
//      asset blocks the publish loudly (release stays draft);
//   3. a post-publish smoke job probes every landing-page release link and
//      the full required set (red on 404);
//   4. behavioral rehearsal: a release whose asset set is missing
//      fa-extension.zip FAILS the gate (the AC4 dry-run "extension leg
//      artificially absent → release blocked"), a complete one passes, and
//      the smoke/landing modes go red on a 404 link.
// Static lint + stubbed-gh/HTTP harness in the same style as
// release_empty_latest_guard_test.dart.
import 'dart:io';
import 'dart:typed_data';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();

YamlMap workflowYaml(String path) => loadYaml(read(path)) as YamlMap;

/// All `steps[]` of a job as typed maps.
List<YamlMap> jobSteps(String workflowPath, String jobId) {
  final jobs = workflowYaml(workflowPath)['jobs'] as YamlMap;
  return ((jobs[jobId] as YamlMap)['steps'] as YamlList)
      .whereType<YamlMap>()
      .toList();
}

const requiredAssets = <String>[
  'fa-extension.zip',
  'fa-linux-arm64.tar.gz',
  'fa-linux-x64.tar.gz',
  'fa-macos-arm64.tar.gz',
  'fa-macos-x64.tar.gz',
  'fa-web-spa.zip',
  'fa-windows-x64.zip',
];

const gateScript = 'scripts/assert_release_assets.sh';
const requiredList = 'scripts/release_required_assets.txt';

void main() {
  // ── 1. the single source of truth ───────────────────────────────────────
  group('gh-1832: required-assets list (single source of truth)', () {
    test('$requiredList exists and carries the v1.0.634 fa-* set', () {
      final lines = read(requiredList)
          .split('\n')
          .map((l) {
            final i = l.indexOf('#');
            return (i < 0 ? l : l.substring(0, i)).trim();
          })
          .where((l) => l.isNotEmpty)
          .toList();
      for (final asset in requiredAssets) {
        expect(lines, contains(asset),
            reason: '$requiredList must list $asset');
      }
      expect(lines.length, requiredAssets.length,
          reason: 'the list is the release gate — every entry must be a '
              'deliberate, named asset (no extras)');
    });

    test('every entry is a concrete fa-* archive name (no globs/junk)', () {
      final lines = read(requiredList)
          .split('\n')
          .map((l) {
            final i = l.indexOf('#');
            return (i < 0 ? l : l.substring(0, i)).trim();
          })
          .where((l) => l.isNotEmpty)
          .toList();
      for (final line in lines) {
        expect(RegExp(r'^fa-[a-z0-9.-]+\.(zip|tar\.gz)$').hasMatch(line), isTrue,
            reason: 'entry "$line" is not a literal asset name — the gate '
                'matches exact names, globs would silently pass');
      }
    });

    test('site/index.html links fa-extension.zip on the latest alias', () {
      expect(
        read('site/index.html'),
        contains(
            'https://github.com/IstiN/flutter_agent_harness/releases/latest/download/fa-extension.zip'),
        reason: 'the landing link is the smoke subject — if the page '
            'changes shape, the link-check contract must be revisited',
      );
    });
  });

  // ── 2. AC2: the publish point is gated ──────────────────────────────────
  group('gh-1832 AC2: release-provenance publish is asset-gated', () {
    final steps = jobSteps('.github/workflows/ci.yml', 'release-provenance');

    int stepIndex(bool Function(YamlMap) predicate, String what) {
      final i = steps.indexWhere(predicate);
      expect(i, isNonNegative, reason: 'ci.yml release-provenance lacks $what');
      return i;
    }

    test('a gate step invokes assert_release_assets.sh before the flip', () {
      final gate = stepIndex(
        (s) => s['run']?.toString().contains(gateScript) ?? false,
        'the required-assets gate step ($gateScript)',
      );
      final publish = stepIndex(
        (s) => s['run']?.toString().contains('--draft=false --latest') ?? false,
        'the --draft=false --latest publish flip',
      );
      expect(gate < publish, isTrue,
          reason: 'the gate MUST run before the publish flip — a missing '
              'asset must leave the release a draft (previous stays latest) '
              'and go red, never publish a partial release (gh-1832)');
    });

    test('the gate step reads the checked-in list via the script, not a '
        'private copy', () {
      final gate = steps
          .firstWhere((s) => s['run']?.toString().contains(gateScript) ?? false);
      expect(gate['run'].toString(), contains('assert_release_assets.sh'));
      // No inline asset enumeration in the step: the single source of
      // truth is the list file, consumed inside the script.
      for (final asset in requiredAssets) {
        expect(gate['run'].toString(), isNot(contains(asset)),
            reason: 'the gate step must not duplicate the asset list — '
                'keep the one list in $requiredList');
      }
    });
  });

  // ── 3. AC3: post-publish smoke job ──────────────────────────────────────
  group('gh-1832 AC3: release-asset-smoke job', () {
    final jobs = workflowYaml('.github/workflows/ci.yml')['jobs'] as YamlMap;
    final smoke = jobs['release-asset-smoke'] as YamlMap?;

    test('exists, needs release-provenance, and is tag-train-only', () {
      expect(smoke, isNotNull,
          reason: 'ci.yml must carry a release-asset-smoke job (gh-1832)');
      // `needs:` may parse as a scalar (single dependency) or a list.
      final needs = smoke!['needs'];
      final needsList =
          needs is YamlList ? needs.toList() : <String>[needs.toString()];
      expect(needsList, contains('release-provenance'));
      final cond = smoke['if'].toString();
      expect(cond, contains("startsWith(github.ref, 'refs/tags/v')"),
          reason: 'the smoke rides the tag train — PR runs must not probe '
              'release URLs');
    });

    test('probes BOTH the landing-page links and the full required set', () {
      final runs = (smoke!['steps'] as YamlList)
          .whereType<YamlMap>()
          .map((s) => s['run']?.toString() ?? '')
          .toList();
      expect(runs.any((r) => r.contains('--landing')), isTrue,
          reason: 'the landing page must gain a CI link-check over the '
              'release URLs it exposes (gh-1832 AC3)');
      expect(runs.any((r) => r.contains('--smoke')), isTrue,
          reason: 'the smoke must download the full required set, not only '
              'the links the landing page happens to expose');
    });

    test('smoke job checks out the repo (needs site/index.html + script)', () {
      final uses = (smoke!['steps'] as YamlList)
          .whereType<YamlMap>()
          .map((s) => s['uses']?.toString() ?? '')
          .toList();
      expect(uses.any((u) => u.startsWith('actions/checkout')), isTrue);
    });
  });

  // ── 4. behavioral: gate + smoke against stubbed gh / local HTTP ────────
  group('gh-1832 behavioral (stubbed gh, local HTTP)', () {
    late Directory root;
    late String bin;

    setUp(() {
      root = Directory.systemTemp.createTempSync('gh1832-gate-');
      bin = '${root.path}/bin';
      Directory(bin).createSync();
    });

    tearDown(() {
      root.deleteSync(recursive: true);
    });

    /// Run the gate script with a stubbed `gh` whose `release view --json
    /// assets --jq '.assets[].name'` prints [assets].
    ProcessResult runGate(List<String> assets) {
      final fixture = '${root.path}/assets.txt';
      File(fixture).writeAsStringSync(assets.isEmpty ? '' : '${assets.join('\n')}\n');
      File('$bin/gh').writeAsStringSync(
        '#!/usr/bin/env bash\n'
        'case "\$1 \$2" in\n'
        '  "release view") cat "\$FA_GH_ASSETS_FIXTURE" ;;\n'
        '  *) echo "unexpected gh call: \$*" >> "\$FA_GH_ASSETS_FIXTURE"; exit 64 ;;\n'
        'esac\n',
      );
      Process.runSync('chmod', ['+x', '$bin/gh']);
      return Process.runSync(
        'bash',
        [gateScript, 'v9.9.9'],
        environment: {
          'PATH': '$bin:${Platform.environment['PATH']}',
          'GITHUB_REPOSITORY': 'OWNER/REPO',
          'GH_TOKEN': 'stub',
          'FA_GH_ASSETS_FIXTURE': fixture,
        },
        includeParentEnvironment: false,
        workingDirectory: Directory.current.path,
      );
    }

    test('AC4 rehearsal: extension leg artificially absent → release blocked',
        () {
      final complete = [...requiredAssets]..remove('fa-extension.zip');
      final res = runGate(complete);
      final out = '${res.stdout}${res.stderr}';
      expect(res.exitCode, isNot(0),
          reason: 'a release missing fa-extension.zip must FAIL the gate '
              '(v1.0.635 published exactly this way)');
      expect(out, contains('fa-extension.zip'),
          reason: 'the gate must name the missing asset');
    });

    test('complete asset set passes the gate', () {
      final res = runGate(requiredAssets);
      expect(res.exitCode, 0,
          reason: '${res.stdout}${res.stderr}');
    });

    Future<HttpServer> bindServer(Map<String, int> statusByPath) async {
      final server = await HttpServer.bind('127.0.0.1', 0);
      server.listen((req) async {
        final status = statusByPath[req.uri.path] ?? 500;
        req.response.statusCode = status;
        req.response.add(Uint8List.fromList(const [0x50, 0x4b]));
        await req.response.close();
      });
      return server;
    }

    test('--smoke goes red on a 404 asset, green when all serve', () async {
      final server = await bindServer({
        for (final a in requiredAssets) '/OWNER/REPO/releases/download/v9.9.9/$a': 200,
      });
      final base = 'http://127.0.0.1:${server.port}';
      // Process.run (NOT runSync): the fixture HttpServer lives in THIS
      // isolate's event loop — a synchronous run would block accepts while
      // the script's curl waits, deadlocking to curl's --max-time.
      Future<ProcessResult> run(String tag) => Process.run(
            'bash',
            [gateScript, '--smoke', tag],
            environment: {
              'PATH': Platform.environment['PATH']!,
              'GITHUB_REPOSITORY': 'OWNER/REPO',
              'FA_RELEASE_DOWNLOAD_BASE': base,
            },
            includeParentEnvironment: false,
            workingDirectory: Directory.current.path,
          );
      expect((await run('v9.9.9')).exitCode, 0,
          reason: 'all assets serve → green');

      // Now fa-extension.zip 404s (the v1.0.635 condition).
      await server.close(force: true);
      final server2 = await bindServer({
        for (final a in requiredAssets)
          if (a != 'fa-extension.zip')
            '/OWNER/REPO/releases/download/v9.9.9/$a': 200,
        '/OWNER/REPO/releases/download/v9.9.9/fa-extension.zip': 404,
      });
      final res = await Process.run(
        'bash',
        [gateScript, '--smoke', 'v9.9.9'],
        environment: {
          'PATH': Platform.environment['PATH']!,
          'GITHUB_REPOSITORY': 'OWNER/REPO',
          'FA_RELEASE_DOWNLOAD_BASE': 'http://127.0.0.1:${server2.port}',
        },
        includeParentEnvironment: false,
        workingDirectory: Directory.current.path,
      );
      await server2.close(force: true);
      final out = '${res.stdout}${res.stderr}';
      expect(res.exitCode, isNot(0), reason: 'a 404 asset must go red');
      expect(out, contains('fa-extension.zip'));
    });

    test('--landing probes every release link on the page, red on 404',
        () async {
      final page = '${root.path}/landing.html';
      Future<HttpServer> serverWith(bool extension404) async {
        return bindServer({
          '/IstiN/flutter_agent_harness/releases/latest/download/fa-extension.zip':
              extension404 ? 404 : 200,
          '/IstiN/flutter_agent_harness/releases/download/v9.9.9/fa-web-spa.zip':
              200,
        });
      }

      var server = await serverWith(false);
      File(page).writeAsStringSync('<a class="btn" id="extension-download" '
          'href="http://127.0.0.1:${server.port}/IstiN/flutter_agent_harness/releases/latest/download/fa-extension.zip">'
          'Download</a> and '
          'href="http://127.0.0.1:${server.port}/IstiN/flutter_agent_harness/releases/download/v9.9.9/fa-web-spa.zip". '
          'Trailing-comma guard: .../fa-extension.zip,\n');
      // Async run — see the --smoke note: runSync starves the server.
      final res = await Process.run(
        'bash',
        [gateScript, '--landing', page],
        environment: {'PATH': Platform.environment['PATH']!},
        includeParentEnvironment: false,
        workingDirectory: Directory.current.path,
      );
      expect(res.exitCode, 0, reason: '${res.stdout}${res.stderr}');

      // Same page, but the extension link now 404s (v1.0.635 incident).
      await server.close(force: true);
      server = await serverWith(true);
      File(page).writeAsStringSync('<a href="http://127.0.0.1:${server.port}'
          '/IstiN/flutter_agent_harness/releases/latest/download/fa-extension.zip">d</a>\n');
      final res2 = await Process.run(
        'bash',
        [gateScript, '--landing', page],
        environment: {'PATH': Platform.environment['PATH']!},
        includeParentEnvironment: false,
        workingDirectory: Directory.current.path,
      );
      await server.close(force: true);
      expect(res2.exitCode, isNot(0),
          reason: 'a 404 landing link must go red (the owner-facing symptom)');
    });
  });
}

// gh-1684 — the fa-extension.zip size budget regression surfaced ONLY
// at deploy time (pages.yml), after #1631 merged, and blocked Pages for
// days. Owner direction (locked 2026-10-18):
//  AC1  Pages stops carrying/copying/gating the zip; the site's extension
//       download links point at the GitHub release asset
//       (releases/latest/download/fa-extension.zip),
//  AC2  the zip stays attached to releases by the build-macos.yml
//       build-extension leg (latest tag onward),
//  AC3  the size gate runs at PR review time: a new extension-size-gate
//       leg in ci.yml builds the real zip and fails the PR against the
//       committed baseline (a vendor-bump PR without a reseed goes red),
//  AC4  the notice-only web-app.tsv/outlook-app.tsv legs (baselines never
//       committed since #1096) are REMOVED from pages.yml,
//  AC5  one baseline + one enforcement rule: the release leg and the PR
//       leg gate against the same committed TSV with the identical
//       size_manifest.py invocation, on the same pinned Flutter (3.47.7).
//
// Deliberately YAML-level asserts (same static pattern as
// ci_1267_path_triggered_legs_test.dart / ci_1659_office_addin_matrix_
// test.dart): they pin the wiring — the builds themselves run on CI
// runners, not locally.
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();
YamlMap jobsOf(String workflowPath) =>
    loadYaml(read(workflowPath))['jobs'] as YamlMap;

const ci = '.github/workflows/ci.yml';
const pages = '.github/workflows/pages.yml';
const macos = '.github/workflows/build-macos.yml';
const legId = 'extension-size-gate';

const releaseDownloadUrl =
    'https://github.com/IstiN/flutter_agent_harness/releases/latest/download/fa-extension.zip';

/// The exact gate invocation every fa-extension.zip leg must run
/// (gh-1684 AC5: one baseline, one enforcement rule).
const gateInvocation =
    'python3 scripts/size_manifest.py check build/fa-extension.zip '
    '--baseline scripts/size_budget/fa-extension.tsv';

/// The extsize classifier arm in the changes job. gh-1684 rework also
/// arms the root `vendor/` forks (patch edits are a normal maintenance
/// event and path deps carry no content hash in pubspec.lock), the gate
/// tool itself and root pubspec_overrides.yaml (feeds `dart pub get`
/// for the dart2js agent build, same as pubspec.yaml/pubspec.lock).
final extsizeGrep =
    r"grep -qE '(^browser_ext/|^flutter_app/|^lib/|^packages/|^vendor/"
    r"|^pubspec\.yaml$|^pubspec_overrides\.yaml$|^pubspec\.lock$"
    r"|^scripts/(build_browser_ext|fetch_vendor_assets|stage_extension_panel"
    r"|ext_package_guard|prune_flutter_assets)\."
    r"|^scripts/size_manifest\.py$"
    r"|^scripts/size_budget/fa-extension\.tsv$"
    r"|^\.github/workflows/(ci|build-macos|pages)\.yml$)'";

void main() {
  final ciBody = read(ci);
  final ciJobs = jobsOf(ci);
  final pagesBody = read(pages);
  final macosBody = read(macos);
  final macosJobs = jobsOf(macos);
  final index = read('site/index.html');
  final llms = read('site/llms.txt');

  group('AC1 — Pages stops carrying the zip; site links move', () {
    test('pages.yml no longer copies fa-extension.zip into the artifact', () {
      expect(
        pagesBody,
        isNot(contains('build/pages/root/extension')),
        reason:
            'AC1: the Pages artifact must not contain fa-extension.zip — '
            'the download channel is the GitHub release now',
      );
      expect(
        pagesBody,
        isNot(contains('Build Chrome extension')),
        reason: 'nothing extension-related ships from Pages anymore',
      );
    });

    test('pages.yml runs no size gates at deploy time', () {
      expect(
        pagesBody,
        isNot(contains('Size manifest + budget gate')),
        reason:
            'the deploy-time gate is the wrong layer (this bug) — the '
            'extension gate lives at PR/review time and release time',
      );
      expect(
        pagesBody,
        isNot(contains('upload-artifact')),
        reason:
            'the seeded-baseline ride-along upload is obsolete with '
            'the web-app/outlook-app notice-only legs removed (AC4)',
      );
    });

    test('every site extension link points at the GitHub release', () {
      expect(index, contains(releaseDownloadUrl));
      expect(llms, contains(releaseDownloadUrl));
      expect(
        index + llms,
        isNot(contains('./extension/fa-extension.zip')),
        reason: 'no site-relative extension links may survive',
      );
      expect(
        index + llms,
        isNot(contains('https://fa1.dev/extension/fa-extension.zip')),
        reason: 'no fa1.dev extension-zip links may survive',
      );
      // The FAQ JSON-LD answer is a link too — it must carry the new URL.
      expect(
        index,
        contains('Download fa-extension.zip from $releaseDownloadUrl'),
      );
    });

    test(
      'the llms.txt artifact lead-in matches the release channel (rework)',
      () {
        // AC1 moved the zip channel to Releases: build-macos builds it
        // per release, ci.yml extension-size-gate per PR — deploys no
        // longer touch it, so "(rebuilt on every deploy)" is stale.
        expect(llms, contains('- Artifact (attached to every release):'));
        expect(llms, isNot(contains('rebuilt on every deploy')));
      },
    );
  });

  group('AC2 — the zip keeps riding the release', () {
    test('build-macos.yml build-extension gates then uploads the zip', () {
      final job = macosJobs['build-extension'] as YamlMap?;
      expect(
        job,
        isNotNull,
        reason: 'the release leg is the only release-time builder left',
      );
      final steps = ((job!['steps'] as YamlList).map(
        (s) => s.toString(),
      )).join('\n');
      expect(
        steps,
        contains(gateInvocation),
        reason:
            'gate BEFORE upload — a budget regression must not '
            'reach the release assets',
      );
      expect(
        steps,
        contains(r'gh release upload "$RELEASE_TAG" "$asset"'),
        reason:
            'AC2: fa-extension.zip attached to releases, latest '
            'tag onward (--clobber keeps the stable asset name)',
      );
    });
  });

  group('AC3 — the gate runs at PR review time', () {
    test('the extension-size-gate leg exists in ci.yml', () {
      expect(ciJobs[legId], isNotNull);
    });

    test('the leg is path-gated on the new extsize output', () {
      final cond = (ciJobs[legId] as YamlMap)['if'].toString();
      expect(cond, contains("needs.changes.outputs.extsize == 'true'"));
      // Same two-event guard as exzone/locksmoke/office_addin:
      // pull_request events AND SM validation dispatches.
      expect(cond, contains("github.event_name == 'pull_request'"));
      expect(cond, contains("github.event_name == 'workflow_dispatch'"));
      expect(
        cond,
        contains("needs.release-pending.outputs.pending == 'true'"),
        reason: 'gh-1551: the empty-schedule-tick pre-check gates every leg',
      );
      expect(
        cond,
        contains("needs.release-dedupe.outputs.dedupe != 'true'"),
        reason: 'gh-1625: the release-twin pre-check gates every leg',
      );
    });

    test('the leg builds the full zip and gates against the baseline', () {
      final steps = (((ciJobs[legId] as YamlMap)['steps'] as YamlList).map(
        (s) => s.toString(),
      )).join('\n');
      expect(
        steps,
        contains('bash scripts/build_browser_ext.sh --with-app'),
        reason:
            'the gate must measure the REAL artifact, not a '
            'manifest-only stand-in',
      );
      expect(steps, contains(gateInvocation));
      expect(
        steps,
        isNot(contains('--init-if-missing')),
        reason:
            'the baseline is committed — self-seeding would wave '
            'any regression through',
      );
    });

    test('the leg carries an explicit ceiling (#351 arithmetic)', () {
      expect((ciJobs[legId] as YamlMap)['timeout-minutes'], isNotNull);
    });

    test('the classifier emits extsize for both events', () {
      final outputs = (ciJobs['changes'] as YamlMap)['outputs'] as YamlMap;
      expect(
        outputs['extsize'].toString(),
        contains('steps.paths.outputs.extsize'),
        reason:
            'the output rides the paths step (pull_request + validation '
            'dispatches), NOT the non-PR full-gate filter — tags/schedule '
            'are gated by the release leg instead',
      );
    });

    test('the classifier keys on the extension-touching path set', () {
      final run = ciBody.split('\n  changes:')[1].split('\n  # ─')[0];
      expect(run, contains(extsizeGrep));
      expect(
        ciBody.split(extsizeGrep).length - 1,
        1,
        reason: 'single source — a second copy would let the arms drift',
      );
      // The baseline itself is in the trigger set: a reseed PR must
      // re-run the gate and prove the new floor matches the artifact;
      // a vendor.lock bump without a reseed fails red here.
      expect(extsizeGrep, contains('fa-extension'));
    });

    test('the trigger set arms on root vendor/ fork edits (rework)', () {
      // The vendored forks are real build inputs of the gated artifact
      // (pubspec.yaml → vendor/xterm; pubspec_overrides → vendor/dart_tui;
      // flutter_app/pubspec.yaml → ../vendor/wasm_run*). Path deps carry
      // no content hash in pubspec.lock, so a patched-fork edit can move
      // the zip manifest with no other covered path touched — the exact
      // merge-then-red failure mode gh-1684 exists to kill.
      expect(extsizeGrep, contains('^vendor/'));
      expect(
        ciBody.split('\n  changes:')[1].split('\n  # ─')[0],
        contains(r'|^packages/|^vendor/'),
        reason:
            'the root vendor tree must sit in the same alternation, '
            'not a second grep arm that could drift',
      );
    });

    test('the trigger set arms on the gate tool itself (rework)', () {
      // A scripts/size_manifest.py change (rev normalization, budget
      // math, is_vendored split) must re-run the gate that runs it —
      // the always-on core tests cover correctness, not enforcement.
      expect(extsizeGrep, contains(r'^scripts/size_manifest\.py$'));
    });

    test('the trigger set arms on root pubspec_overrides.yaml (rework)', () {
      // The overrides file selects the vendored dart_tui fork for the
      // dart2js agent build — same supply-chain surface as
      // pubspec.yaml/pubspec.lock, which are already armed.
      expect(extsizeGrep, contains(r'^pubspec_overrides\.yaml$'));
    });

    test('the classifier failure arm runs the leg (fail-safe)', () {
      final run = ciBody.split('\n  changes:')[1].split('\n  # ─')[0];
      expect(run, contains('echo "extsize=true"'));
      expect(
        run,
        contains(
          'failing safe: exzone + locksmoke + installer + office_addin + extsize arms run',
        ),
      );
    });

    test('the extsize arm classifies validation dispatches too', () {
      final run = ciBody.split('\n  changes:')[1].split('\n  # ─')[0];
      final armAt = run.indexOf(extsizeGrep);
      final dispatchExitAt = run.indexOf('!= "pull_request"');
      expect(armAt, greaterThan(-1));
      expect(dispatchExitAt, greaterThan(-1));
      expect(
        armAt < dispatchExitAt,
        isTrue,
        reason:
            'the arm must sit before the dispatch early-exit — the SM '
            'validation dispatch IS the pre-merge gate (dispatch-only '
            'CI); a classification after the exit is path-blind there',
      );
    });

    test('quality-gate NEEDS the leg and consumes its result', () {
      final gate = ciJobs['quality-gate'] as YamlMap;
      final needs = gate['needs'];
      final needsList = needs is YamlList
          ? needs.map((n) => n.toString())
          : [needs!];
      expect(
        needsList,
        contains(legId),
        reason:
            'a leg outside the aggregate never blocks the merge — the '
            'quality gate is the single required check',
      );
      expect(
        ciBody,
        contains('R_EXT_SIZE: \${{ needs.extension-size-gate.result }}'),
      );
      expect(
        ciBody,
        contains('"extension-size-gate:\$R_EXT_SIZE"'),
        reason:
            'the verdict loop must consume the result — an unlisted need '
            'reports in the log and gates nothing',
      );
    });

    test('the leg is platform class (never holds the dart publish)', () {
      final gateRun = ciBody.split('\n  quality-gate:')[1].split('\n  # ─')[0];
      final caseBody = gateRun.split('case "\$name" in')[1].split('esac')[0];
      expect(
        caseBody,
        contains('extension-size-gate'),
        reason:
            '#1368 platform class: a red size gate reddens the required '
            'aggregate (blocks the MERGE) but never gates dart_ok — a '
            'zip-size red must not hold the pure-Dart publish hostage',
      );
    });
  });

  group('AC4 — the notice-only web gates are removed, not armed', () {
    test('pages.yml has no web-app/outlook-app gate legs left', () {
      expect(pagesBody, isNot(contains('web-app.tsv')));
      expect(pagesBody, isNot(contains('outlook-app.tsv')));
      expect(
        pagesBody,
        isNot(contains('--init-if-missing')),
        reason:
            'the baselines were never committed — the legs were '
            'notice-only since #1096; removed per gh-1684 decision 5',
      );
    });
  });

  group('AC5 — one baseline, one enforcement rule', () {
    test('both legs gate against the committed baseline identically', () {
      expect(macosBody, contains(gateInvocation));
      expect(ciBody, contains(gateInvocation));
      expect(macosBody.split(gateInvocation).length - 1, 1);
      expect(
        ciBody.split(gateInvocation).length - 1,
        1,
        reason:
            'single invocation per file — drift would resurrect '
            'the two-legs-green-one-leg-red class',
      );
    });

    test('the release leg builds on the same pinned Flutter', () {
      // The pages.yml leg that used to carry this pin is retired; every
      // REMAINING fa-extension.zip builder pins 3.47.7 exactly (#1431:
      // a wildcard pin re-resolves a new engine build per patch drop).
      // Raw-text assert: the parsed view renders the pin unquoted, the
      // file carries it quoted.
      final jobBody = macosBody
          .split('\n  build-extension:')[1]
          .split('\n  release-macos:')[0];
      expect(
        jobBody,
        contains("flutter-version: '3.47.7'"),
        reason:
            'gh-1684 decision 4: the old unpinned channel: stable was '
            'one of the two ways the release and Pages legs diverged',
      );
      final ciSteps = (((ciJobs[legId] as YamlMap)['steps'] as YamlList).map(
        (s) => s.toString(),
      )).join('\n');
      expect(ciSteps, contains('flutter-version: 3.47.7'));
    });

    test('the gate leg caches the pinned Flutter SDK (rework)', () {
      // Sibling legs (e.g. office-addin-suite, the template this leg
      // was modeled on) set cache: true — the pin (not the cache)
      // keeps the engine rev stable, and a cache miss re-resolves the
      // same pinned version, so build comparability is unaffected.
      final flutterStep = ((ciJobs[legId] as YamlMap)['steps'] as YamlList)
          .map((s) => s.toString())
          .firstWhere((s) => s.contains('flutter-version: 3.47.7'));
      expect(
        flutterStep,
        contains('cache: true'),
        reason:
            'the gate fires on the high-churn paths — an uncached '
            'SDK download taxes every one of those runs',
      );
    });
  });
}

@TestOn('vm')
library;

import 'dart:io';

import 'package:flutter_agent_memory/flutter_agent_memory.dart';
import 'package:test/test.dart';

/// gh-1845 rework (PR #1846, review thread PRRT_kwDOTXdlLc6v6eZe):
/// the recovery-playbook note `n_1012_*` documents a once-daily
/// build-extension producer gap (gh-1832 class) and, per the review
/// thread, must reference the filed systemic-fix follow-up issue.
///
/// The note's merge-friendly id carries a 4-hex content-hash suffix
/// (md5 of `normalizeMemoryText(primaryText)`, per
/// `flutter_agent_memory` `MemoryIdScheme`) — the body paragraph IS the
/// hashed text, so appending the follow-up reference invalidates the
/// suffix unless the id (and filename) is recomputed. These tests pin
/// both invariants so future enrichments of the note keep the scheme
/// honest.

void main() {
  group('gh-1845 recovery-playbook note (n_1012)', () {
    /// The note file is renamed whenever its hash suffix is recomputed,
    /// so resolve it by sequential index rather than full name.
    File findNote() {
      final files = Directory('memory/note')
          .listSync()
          .whereType<File>()
          .where((f) => RegExp(r'n_1012_[0-9a-f]{4}\.md$').hasMatch(f.path))
          .toList();
      expect(files, hasLength(1), reason: 'exactly one n_1012 note');
      return files.single;
    }

    /// The hashed primary text: the first body paragraph after the
    /// `# Note: <id>` heading (frontmatter and the `**By:**` trailer
    /// are never hashed).
    String primaryText(File file) {
      final body = file.readAsStringSync().replaceFirst(
        RegExp(r'^---\n.*?\n---\n', dotAll: true),
        '',
      );
      final blocks = body
          .split(RegExp(r'\n\s*\n'))
          .map((b) => b.trim())
          .where((b) => b.isNotEmpty && !b.startsWith('# Note:'))
          .toList();
      return blocks.first;
    }

    test('body references the filed systemic-fix follow-up issue', () {
      final note = findNote();
      final text = primaryText(note);
      // The review thread asked for a `gh-NNNN` reference to a follow-up
